links={'/':'index.html','/shop':'shop.html','/event':'tournaments.html','/trove-home':'index.html','/trove-community':'community.html','/about-trove':'about.html','/visit-trove':'visit.html','/start-playing':'beginner.html','/contactus':'visit.html','/my/orders':'#account'}
def resolve(body):
 for call,replacement in [('categories',category_block),('products',product_block()),('events',event_block()),('contact',contact)]:body=body.replace(f'<t t-call="gamers_trove_website.{call}"/>',replacement)
 tree=etree.fromstring('<div>'+body+'</div>')
 for node in tree.iter():
  if node.get('t-att-href'):
   expr=node.get('t-att-href');node.set('href','https://www.instagram.com/gamerstrovett/' if 'instagram' in expr else 'https://www.facebook.com/GamersTroveTT/')
  for key in list(node.attrib):
   if key.startswith('t-'):del node.attrib[key]
  if node.get('href') in links:node.set('href',links[node.get('href')])
  if node.get('src','').startswith('/gamers_trove_website/static/src/img/'):node.set('src','assets/'+node.get('src').split('/')[-1])
 return ''.join(etree.tostring(c,method='html',encoding='unicode') for c in tree)
